  const [sel, setSel] = useState(items[0])
  return (
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 180px)', gap: 20 }}>
      {items.map((t) => <SelectableCard key={t} title={t} description="per 100 kcal" selected={sel === t} onSelect={() => setSel(t)} />)}
